def table(headers,rows):return '<table><thead><tr>'+''.join('<th>'+html.escape(str(x))+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+html.escape(str(x))+'</td>' for x in r)+'</tr>' for r in rows)+'</tbody></table>'
def main():
 O.mkdir(exist_ok=False)
 folders=['stance_diagnosis_219','stance_audit_220','centered_path_check_221','centered_path_audit_222','centered_contact_refinement_223','centered_contact_audit_224','lateral_demand_refinement_225','lateral_demand_audit_226','centered_orientation_refinement_v2_227','centered_orientation_audit_v2_228','orientation_force_recovery_227']
 sources={};audits=[]
 for folder in folders:
  p=D/folder;man=read(p/'SHA256.json')
  for f,h in man.items():assert sha(p/f)==h,(folder,f)
  sources[str(p/'SHA256.json')]=sha(p/'SHA256.json')
  for f in ['results.json','independent_audit.json','revision.json','recovery.json']:
   if (p/f).exists():shutil.copy2(p/f,O/(folder+'_'+f));sources[str(p/f)]=sha(p/f)
  if (p/'independent_audit.json').exists():
   a=read(p/'independent_audit.json');assert a['passed'];audits.append(dict(folder=folder,records=a.get('records',a.get('case_windows')),max_geometry_error=a.get('max_geometry_error'),max_work_error_Nm=a.get('max_virtual_work_error_Nm'),filter_replay=a.get('filter_replay'),unavailable_force_records=a.get('force_unavailable_geometry_records',0)))
 diag=read(D/'stance_diagnosis_219/results.json');shutil.copy2(D/'stance_diagnosis_219/stance_and_velocity.png',O/'stance_and_velocity.png')
 labels={0:'36 cm / +15°',2:'36 cm / +20°',6:'37 cm / +16.25°',10:'36.5 cm / +17.5°'};model=[]
 for name,cases in [('centered_path_check_221',[0,2,6,10]),('centered_contact_refinement_223',[0,6]),('lateral_demand_refinement_225',[0,6]),('centered_orientation_refinement_v2_227',[0,2,6,10])]:
  for c in cases:
   z=read(D/name/f'case_{c}.json');p=z['plan'];summary=p['summary'];zz=z.get('summary',{});model.append(dict(study=name,case=c,geometry=labels[c],clearance_mm=summary['minimum_housing_clearance_mm'],model_passed=p['model_passed'],research_pass=zz.get('research_pass'),parameters=z['endpoint_parameters'],command_margin_rad=summary['minimum_command_margin_rad'],evaluations=zz.get('evaluations',1),schedule=z.get('schedule',{}),assumed_foot_difference_BW=zz.get('maximum_assumed_foot_load_difference_BW'),ankle_roll_change_rad=zz.get('maximum_ankle_roll_command_change_rad')))
 (O/'model_comparisons.json').write_text(json.dumps(model,indent=2));(O/'audit_summary.json').write_text(json.dumps(audits,indent=2))
 fig,ax=plt.subplots(1,2,figsize=(12,5),constrained_layout=True)
 styles=[('centered_path_check_221','Centered, original orientation'),('centered_contact_refinement_223','Centered x/pitch refinement'),('lateral_demand_refinement_225','Reduced lateral shift'),('centered_orientation_refinement_v2_227','Centered orientation refinement')]
 for i,(study,label) in enumerate(styles):
  rr=[r for r in model if r['study']==study];ax[0].scatter([list(labels).index(r['case'])+(i-1.5)*.08 for r in rr],[r['clearance_mm'] for r in rr],s=50,label=label)
 ax[0].axhline(3,color='k',ls='--',label='Unchanged 3 mm model screen');ax[0].set_xticks(range(4),list(labels.values()),rotation=20,ha='right');ax[0].set_ylabel('Minimum sampled housing clearance (mm)');ax[0].set_title('Full 91-knot model paths');ax[0].legend(fontsize=7)
 for i,(study,label) in enumerate(styles[2:]):
  rr=[r for r in model if r['study']==study and r['case'] in [0,6]];ax[1].bar(np.arange(2)+(i-.5)*.3,[abs(r['parameters'][1])*1000 for r in rr],.3,label=label)
 ax[1].axhline(50,color='gray',ls='--',label='Prior selected paths: 50 mm');ax[1].set_xticks([0,1],[labels[0],labels[6]]);ax[1].set_ylabel('Planned lateral root displacement (mm)');ax[1].set_title('Reducing lateral stance demand');ax[1].legend(fontsize=8)
 fig.savefig(O/'model_constraints.png',dpi=180);plt.close(fig)
 # All original physical outcomes stay unchanged; no model result is a physical episode.
 summary=dict(utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),repair_complete=False,task_complete=False,physical_admission=False,best_verified='current_retention_09',best=dict(clean=64,stable=70,total=72,slipping=8,housing=2,conservative_warnings=50,strict_clean=22),latest_physical_probe='bias_probe_210',new_full20s_trials=0,new_active_physics_ticks=0,new_optimizer_updates=0,fresh_holdout_started=False,ppo_started=False,video_unchanged='all_attempts_video_213/all_attempts.mp4',video_duration_s=58.4,model_rows=model,audits=audits,source_sha256=sources)
 (O/'summary.json').write_text(json.dumps(summary,indent=2))
 tbody=[[r['study'],r['geometry'],f"{r['clearance_mm']:.6f}",r['model_passed'],r['research_pass'],f"{r['parameters'][1]*1000:.3f}",r['evaluations'],r['schedule'].get('duration_s','not run'),r['schedule'].get('time_gate_passed','not run')] for r in model]
 physical=table(['Bank / scope','Stable','Clean','Slipping','Unwanted contact'],[['Verified09 known-old',22,20,4,'2 housing'],['Verified09 transfer',24,22,2,0],['Verified09 recent',24,22,2,0],['Verified09 TOTAL',70,64,8,'2 housing'],['Latest rejected isolating probe210',18,14,6,'2 housing']])
 raw=[]
 for z in diag['rows']:
  if z['case'] in [0,1,6,7] and z['raw_settling_available'] and z['window']==[11.,14.9]:
   js=[next(j for j in z['joints'] if j['joint']==s+'_ankle_roll_joint') for s in ['left','right']];raw.append([z['run'],z['case'],*[f"{a['normal_load_median_bw']:.4f}" for a in z['feet']],*[f"{j['raw_qd_abs_median_rad_s']:.4f}" for j in js],*[f"{j['raw_q_range_rad']*1000:.4f}" for j in js]])
 txt='''<!doctype html><html><head><meta charset="utf-8"><title>Low-seat stance and contact planning — round229</title><style>body{font:16px/1.5 system-ui;background:#f4f6f9;color:#172237;max-width:1220px;margin:auto;padding:32px}h1,h2{line-height:1.2}section{background:white;padding:22px;margin:20px 0;border-radius:12px}table{border-collapse:collapse;font-size:13px;width:100%}td,th{border-bottom:1px solid #dbe1ea;padding:8px;text-align:left}th{background:#edf2f8}img{width:100%;height:auto}video{width:100%;max-height:650px}.notice{background:#fff1db;border-left:5px solid #bd6600;padding:18px}.scroll{overflow-x:auto}code{word-break:break-word}</style></head><body>'''
 txt+='<h1>Stance diagnosis and bounded contact planning</h1><p class="notice"><b>Repair remains unresolved.</b> All 64 established successes remain protected. Eight slipping trials and two housing-contact cases remain in the best verified controller. This round ran offline calculations only: zero new physical episodes, optimizer updates or fresh-holdout evaluations.</p>'
 txt+='<section><h2>Physical outcomes come first</h2>'+physical+'<p>The four selected probe210 cases remained unsupported at a hover. Their absence of slip is not successful sitting. No new 72-case retention or PPO comparison has occurred. The 50 conservative warning cases and 22 strict-clean cases in verified09 are separate from physical failure labels.</p></section>'
 txt+='<section><h2>Recorded stance evidence</h2><p>Across all 24 cases in three recorded studies, diagnosis219 checked 144 case-windows and all 37 joints. Raw 20 ms qd is available only for the four selected cases in178/210. The prior paths deliberately moved the root laterally by ±50 mm. During hover the floor loads became asymmetric and ankle-roll qd dominated the unchanged settling guard. This is an association, not proof of causation. Raw qd and sampled position differences remain distinct; neither replaces the other.</p><img src="stance_and_velocity.png">'+table(['Recorded run','Case','Left load / BW','Right load / BW','Left |qd| rad/s','Right |qd| rad/s','Left q range mrad','Right q range mrad'],raw)+'</section>'
 txt+='<section><h2>Complete sampled model paths</h2><p>Every listed result is a 91-knot fixed-foot path using measured saved development inputs, the corrected cooked collision model and frozen inertia. Positive-gap nodes carry zero modeled seat force; later loads are explicitly assumed, never called sensed. Whole-path model passes and command-only schedules do not certify dynamic tracking, actual support, quiet settling, parent composition or retention. A local failure does not prove impossibility.</p><img src="model_constraints.png"><div class="scroll">'+table(['Offline study','Geometry','Min clearance mm','Model pass','Research pass','Root y mm','Coarse evaluations','Command-only seconds','Time pass'],tbody)+'</div><p>Study225 additionally required a 3.2 mm research reserve. Study227 maximizes clearance under the unchanged 3 mm screen while fixing lateral translation to zero and adding separate research limits of 0.1 BW assumed left/right load difference and 0.04 rad ankle-roll command change. These are different recorded research objectives; the physical criteria never changed.</p></section>'
 txt+='<section><h2>Independent checks and preserved failure</h2>'+table(['Audit','Records','Maximum geometry error','Max virtual-work error Nm','Unavailable force records'],[[a['folder'],a['records'],a['max_geometry_error'],a['max_work_error_Nm'],a['unavailable_force_records']] for a in audits])+'<p>The original227 search stopped after five saved candidates when another candidate lacked a feasible force allocation and the reallocator expected missing corner data. The original source, log and outputs remain preserved. V2 reuses all five, records unavailable force data as unavailable and permits only 34 new case0 builds: at most40 original-plus-recovery coarse builds. Other cases retain40. No force data, success, tolerance increase or extra physical attempt was invented. Audit228 checks all geometry and available allocations; unavailable force paths retain failed gates and are not an infeasibility proof.</p></section>'
 txt+='<section><h2>Effort and complete-attempt video</h2><p>No new full-duration effort result exists. All earlier effort uses approximate implicit-PD telemetry, not direct solver or hardware motor effort. Verified09 matched61111 on common clean pairs; versus selected62111@8 on20 old-development common clean trials, whole20 torque² was4.38% higher and final5 was25.45% higher. Failed or hovering fragments do not count as savings.</p><video controls preload="metadata" src="../all_attempts_video_213/all_attempts.mp4"></video><p>The unchanged58.4-second video covers all39 recorded sources:816 complete20-second trials (475 clean,341 failed),120 recorded diagnostic prefixes and96 aborted case attempts without saved motion explicitly disclosed. It is a schematic from saved body transforms, not camera footage. The historical repeated/rejected totals are not best-controller accuracy. No new motion was added in219–228.</p></section>'
 txt+='<section><h2>Next admission requirements</h2><p>Any candidate must pass current-input runtime reconstruction, actual filter/guard/parent checks and bounded physical validation before a success claim. Do not weaken the raw-speed quiet guard or unload before measured support. The36/+20 and36.5/+17.5 conditions still require complete feasible transitions. Remove all eight failures and retain all64 successes across72 matched full20s trials before PPO63111/63117. Keep fresh holdout closed and all earlier evidence intact. Reference-assisted rigid-slab simulation is not real-robot or anywhere sitting/leaning validation.</p></section></body></html>'
 (O/'findings.html').write_text(txt);(O/'SHA256.json').write_text(json.dumps({p.name:sha(p) for p in O.iterdir() if p.is_file()},indent=2));print(json.dumps(dict(report=str(O),entries=len(read(O/'SHA256.json')),physics_ticks=0,repair_complete=False)))
